package com.example.HMS.service;

import com.example.HMS.dto.AppointmentDto;
import com.example.HMS.dto.AppointmentMapper;
import com.example.HMS.entity.Appointment;
import com.example.HMS.entity.Doctor;
import com.example.HMS.entity.Patient;
import com.example.HMS.repository.AppointmentRepository;
import com.example.HMS.repository.DoctorRepository;
import com.example.HMS.repository.PatientRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private DoctorRepository doctorRepository;

    @Mock
    private PatientRepository patientRepository;

    @Mock
    private AppointmentMapper appointmentMapper;

    @Test
    // GreyTest trace: updateAppointmentById | IF-2-FALSE, IF-2-TRUE | BR-173 -> TP-031 -> TC-264
    void updateAppointmentById_preservesOrUpdatesDoctorAccordingToDto() {
        Doctor doctor10 = new Doctor();
        doctor10.setDoctorId(10L);
        Doctor doctor11 = new Doctor();
        doctor11.setDoctorId(11L);
        Patient patient20 = new Patient();
        patient20.setPatientId(20L);
        Appointment appointment = new Appointment();
        appointment.setAppointmentId(501L);
        appointment.setDoctor(doctor10);
        appointment.setPatient(patient20);
        AppointmentDto unchangedDoctorDto = new AppointmentDto(501L, 10L, 20L, null, null, null, null);
        AppointmentDto updateDoctorDto = new AppointmentDto(null, 11L, null, null, null, null, null);
        AppointmentDto firstResult = new AppointmentDto(501L, 10L, 20L, null, null, null, null);
        AppointmentDto secondResult = new AppointmentDto(501L, 11L, 20L, null, null, null, null);

        when(appointmentRepository.findById(501L)).thenReturn(Optional.of(appointment), Optional.of(appointment));
        when(doctorRepository.findById(11L)).thenReturn(Optional.of(doctor11));
        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> invocation.getArgument(0));
        when(appointmentMapper.toDto(appointment)).thenReturn(firstResult, secondResult);

        AppointmentService service = new AppointmentService(appointmentRepository, doctorRepository, patientRepository, appointmentMapper);
        AppointmentDto first = service.updateAppointmentById(501L, unchangedDoctorDto);
        assertSame(doctor10, appointment.getDoctor());
        assertSame(patient20, appointment.getPatient());
        assertEquals(10L, first.getDoctorId());

        AppointmentDto second = service.updateAppointmentById(501L, updateDoctorDto);
        assertSame(doctor11, appointment.getDoctor());
        assertSame(patient20, appointment.getPatient());
        assertEquals(11L, second.getDoctorId());

        verify(appointmentRepository, times(2)).findById(501L);
        verify(doctorRepository).findById(11L);
        verify(appointmentRepository, times(2)).save(any(Appointment.class));
        verify(appointmentMapper, times(2)).toDto(appointment);
    }
}
